import{_ as a,o as t,c as r,ag as i}from"./chunks/framework.D9ghT4bC.js";const m=JSON.parse('{"title":"Terms of Service","description":"","frontmatter":{},"headers":[],"relativePath":"Terms-of-Service.md","filePath":"Terms-of-Service.md"}'),s={name:"Terms-of-Service.md"};function o(n,e,l,c,h,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="terms-of-service" tabindex="-1">Terms of Service <a class="header-anchor" href="#terms-of-service" aria-label="Permalink to &quot;Terms of Service&quot;">​</a></h1><p>These terms apply to the community services provided for UncivCN: the community multiplayer servers, the community download server and this documentation site. The services are built and maintained by volunteers of the UncivCN community as a personal, non-commercial effort. They are <strong>not</strong> official services: Unciv itself is made by the upstream team at <a href="https://github.com/yairm210/Unciv" target="_blank" rel="noreferrer">https://github.com/yairm210/Unciv</a>, which is not involved in and not responsible for these services. By using any of them you accept these terms and the <a href="/Unciv/Privacy-Policy.html">Privacy Policy</a>.</p><h2 id="_1-what-the-services-are" tabindex="-1">1. What the services are <a class="header-anchor" href="#_1-what-the-services-are" aria-label="Permalink to &quot;1. What the services are&quot;">​</a></h2><ul><li><strong>Multiplayer servers</strong>: uploading and downloading save files, simultaneous turns and optional in-game chat.</li><li><strong>Download server</strong>: serving the UncivCN version manifest and download links (the installers themselves are hosted on GitHub Releases).</li><li><strong>Documentation site</strong>: project documentation and changelogs.</li></ul><p>All of it is free, non-commercial technical infrastructure maintained by community volunteers as a personal effort. <strong>We provide technical infrastructure only and do not publish or operate the game itself</strong>: no payment, subscription or in-game item is sold here. The documentation site and installers are hosted on third-party platforms such as GitHub; when you visit them you are dealing with those platforms directly.</p><h2 id="_2-minors" tabindex="-1">2. Minors <a class="header-anchor" href="#_2-minors" aria-label="Permalink to &quot;2. Minors&quot;">​</a></h2><p>These services are <strong>intended for adults aged 18 or over</strong>. If you are under 18, please do not use them; if you do need to use them, you must do so with your guardian&#39;s consent and guidance, and your guardian must accept these terms and the <a href="/Unciv/Privacy-Policy.html">Privacy Policy</a>.</p><p>We do not intend to provide these services to minors, and we do not collect minors&#39; personal information for marketing or push notifications. If you are a guardian and find that a minor has used these services without consent, contact us using the details below and we will delete the relevant data.</p><h2 id="_3-accounts" tabindex="-1">3. Accounts <a class="header-anchor" href="#_3-accounts" aria-label="Permalink to &quot;3. Accounts&quot;">​</a></h2><ul><li>Your player ID is generated by the game client. Keep your password safe and do not reuse a password from another service.</li><li>Servers may run in approved-registration mode: a new account can only use multiplayer features after an administrator confirms it.</li><li>Do not share, lend or sell accounts. Everything done with an account is treated as done by its owner.</li><li>Tell us if you think your account has been compromised.</li></ul><h2 id="_4-acceptable-use" tabindex="-1">4. Acceptable use <a class="header-anchor" href="#_4-acceptable-use" aria-label="Permalink to &quot;4. Acceptable use&quot;">​</a></h2><p>Do not:</p><ul><li>post or upload anything illegal, hateful or harassing (this includes chat messages and text inside save files);</li><li>upload other players&#39; saves, cheats or malicious data;</li><li>attack, scan, crawl, overload or bypass the rate limits of the servers;</li><li>use the services for commercial activity;</li><li>impersonate the maintainers, the upstream project or other players.</li></ul><p>We may warn, delete data, block accounts, or report to the authorities in serious cases.</p><h2 id="_5-saves-and-data" tabindex="-1">5. Saves and data <a class="header-anchor" href="#_5-saves-and-data" aria-label="Permalink to &quot;5. Saves and data&quot;">​</a></h2><ul><li>Saves on the multiplayer servers exist to move turns between players. Always keep your own local backup.</li><li>We may pause the services or clear data because of legal requirements, force majeure, hardware failure or service changes. We will announce this in the community as early as we can and offer an export path for saves, but we cannot be held liable for lost data.</li><li>If a service is changed or shut down, contact us through the QQ group or GitHub Issues to export your saves.</li></ul><h2 id="_6-disclaimer" tabindex="-1">6. Disclaimer <a class="header-anchor" href="#_6-disclaimer" aria-label="Permalink to &quot;6. Disclaimer&quot;">​</a></h2><p>The services are provided &quot;as is&quot;, without warranty of availability, continuity or data integrity. Disputes between players (including behaviour inside a game) are not our responsibility. We are not liable for indirect damages; clauses that the applicable law does not allow to be limited still apply.</p><h2 id="_7-changes-and-termination" tabindex="-1">7. Changes and termination <a class="header-anchor" href="#_7-changes-and-termination" aria-label="Permalink to &quot;7. Changes and termination&quot;">​</a></h2><ul><li>We may change, pause or terminate some or all of the services at any time, especially to comply with legal requirements.</li><li>These terms may be updated; changes are announced on the documentation site and in the changelog. Continuing to use the services means you accept the updated terms.</li><li>These terms are governed by the law of the place where the servers are deployed; we will try to settle any dispute by discussion first.</li></ul><p>Contact: <a href="https://qm.qq.com/q/j92c3iUnZ0" target="_blank" rel="noreferrer">QQ group</a> or <a href="https://github.com/AutumnPizazz/Unciv/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</p>',21)])])}const p=a(s,[["render",o]]);export{m as __pageData,p as default};
